        update();

    if (p->main_frame->is_loaded()) {
        this->p->schedule_background_process();
        update_title_dirty_status();
        p->schedule_auto_reslice_if_needed();
    }
    notify_project_state_changed(ProjectStateChangeReason::Settings);
}

