void finish()
{
    if (m_finished)
        return;
    m_finished = true;
    const int result = m_failures == 0 ? 0 : 1;
    std::cerr << "HARNESS RESULT " << (result == 0 ? "PASS" : "FAIL") << " failures=" << m_failures << '\n';
    m_state->result = result;
    m_state->stop = true;
